function Cart() {
  const cart = JSON.parse(localStorage.getItem('cart')) || [];

  return (
    <div style={{ padding: '20px' }}>
      <h1>Cart</h1>

      {cart.length === 0 ? (
        <p>Cart is empty</p>
      ) : (
        cart.map((item, index) => (
          <div
            key={index}
            style={{
              border: '1px solid gray',
              padding: '10px',
              marginBottom: '10px',
            }}
          >
            <h3>{item.title}</h3>

            <p>{item.description}</p>

            <p>₹ {item.price}</p>
          </div>
        ))
      )}
    </div>
  );
}

export default Cart;
